#!/usr/bin/env bash
# Builds ouch in a Debian container; the Makefile runs it with docker. It
# installs the build tools with the Rust toolchain of Debian, compiles the
# release OUCH_VERSION of ouch and copies what the package needs to /out:
#
#   /out/ouch                the binary
#   /out/depends             the Depends of the package, from dpkg-shlibdeps
#   /out/man/                the man pages, generated by the build
#   /out/completions/        the completions for bash, zsh and fish,
#                            generated by the build
#   /out/README.md           the readme of the release
#   /out/LICENSE             the license of ouch
#
# Everything in /out ends up owned by HOST_UID:HOST_GID, the user who runs
# make.
set -euo pipefail

REPO_URL="https://github.com/ouch-org/ouch.git"

echo "--> Installing build dependencies..."
apt-get update
DEBIAN_FRONTEND=noninteractive apt-get install -y \
  git \
  build-essential \
  pkg-config \
  cargo \
  rustc \
  clang \
  dpkg-dev
echo "--> Using $(rustc --version)"

# The tags of ouch have no v. The rust-toolchain.toml of the release only matters to rustup, so
# cargo builds with the toolchain of Debian, and stops when it is older than the rust-version
# ouch asks for.
echo "--> Cloning ouch ${OUCH_VERSION}..."
git clone --depth 1 --branch "${OUCH_VERSION}" "${REPO_URL}" /usr/src/ouch
cd /usr/src/ouch

# OUCH_ARTIFACTS_FOLDER makes the build write the man pages and completions to that folder.
echo "--> Compiling release binary..."
OUCH_ARTIFACTS_FOLDER=/tmp/artifacts cargo build --release --locked

# dpkg-shlibdeps finds the packages of the libraries the binary links to, and wants a
# debian/control to run in.
echo "--> Finding the dependencies of the binary..."
mkdir -p /tmp/shlibdeps/debian
printf 'Source: ouch\n\nPackage: ouch\nArchitecture: any\n' > /tmp/shlibdeps/debian/control
(cd /tmp/shlibdeps && dpkg-shlibdeps -O /usr/src/ouch/target/release/ouch) | \
  sed -n 's/^shlibs:Depends=//p' > /tmp/depends

echo "--> Copying the results to /out..."
install -d /out/man /out/completions
install -m 0755 target/release/ouch /out/
install -m 0644 /tmp/depends README.md LICENSE /out/
install -m 0644 /tmp/artifacts/*.1 /out/man/
install -m 0644 /tmp/artifacts/ouch.bash /tmp/artifacts/_ouch /tmp/artifacts/ouch.fish /out/completions/
chown -R "${HOST_UID}:${HOST_GID}" /out
